from legacy_index import discover_legacy_tasks


def build_report(index):
    return ', '.join(discover_legacy_tasks(index))

import sys
import unittest
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parents[1] / 'src'))
from report_tasks import build_report


class ReportTasksTests(unittest.TestCase):
    def test_reports_sorted_task_names(self):
        self.assertEqual('alpha, beta', build_report({'tasks': {'beta': {}, 'alpha': {}}}))


if __name__ == '__main__':
    unittest.main()
